use biome_console::markup;
use biome_css_syntax::{
    AnyCssDimension, CssFunction, CssGenericProperty, CssQueryFeaturePlain, CssQueryFeatureRange,
    CssSyntaxKind,
};
use biome_rowan::{AstNode, SyntaxNodeCast, TextRange};

declare_rule! {
    /// Disallow unknown CSS units.
    ///
    /// For details on known CSS units, see the [MDN web docs](https://developer.mozilla.org/en-US/docs/Learn/CSS/Building_blocks/Values_and_units#lengths).
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```css,expect_diagnostic
    /// a {
    ///   width: 10pippx;
    /// }
    /// ```
    ///
    /// ```css,expect_diagnostic
    /// a {
    ///   width: calc(10px + 10pixels);
    /// }
    /// ```
    ///
    /// ### Valid
    ///
    /// ```css
    /// a {
    ///   width: 10px;
    /// }
    /// ```
    ///
    /// ```css
    /// a {
    ///   width: 10Px;
    /// }
    /// ```
    ///
    /// ```css
    /// a {
    ///   width: 10pX;
    /// }
    /// ```
    ///
    pub NoUnknownUnit {
        version: "next",
        name: "noUnknownUnit",
        recommended: true,
        sources: &[RuleSource::Stylelint("unit-no-unknown")],
    }
}

pub struct NoUnknownUnitState {
    unit: String,
    span: TextRange,
}

impl Rule for NoUnknownUnit {
    type Query = Ast<AnyCssDimension>;
    type State = NoUnknownUnitState;
    type Signals = Option<Self::State>;
    type Options = ();

    fn run(ctx: &RuleContext<Self>) -> Option<Self::State> {
        let node = ctx.query();

        // Percentages don't have a unit token, and `%` is always valid.
        let unit_token = match node {
            AnyCssDimension::CssPercentage(_) => return None,
            AnyCssDimension::CssRegularDimension(dimension) => dimension.unit_token().ok()?,
            AnyCssDimension::CssUnknownDimension(dimension) => dimension.unit_token().ok()?,
        };

        let unit = unit_token.text_trimmed();
        let lowercased_unit = unit.to_lowercase();

        // The `x` unit is a resolution unit that is only valid within a
        // resolution context (e.g. `image-set()`, the `resolution` media
        // feature, or the `image-resolution` property).
        if lowercased_unit == "x" {
            if is_in_resolution_context(node) {
                return None;
            }
        } else if is_known_unit(&lowercased_unit) {
            return None;
        }

        Some(NoUnknownUnitState {
            unit: unit.to_string(),
            span: unit_token.text_trimmed_range(),
        })
    }

    fn diagnostic(_: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                state.span,
                markup! {
                    "Unexpected unknown unit: "{state.unit}
                },
            )
            .note(markup! {
                <Hyperlink href="https://developer.mozilla.org/en-US/docs/Learn/CSS/Building_blocks/Values_and_units#lengths">"See MDN web docs for more details."</Hyperlink>
            })
            .footer_list(
                markup! {
                    "Use a known unit instead, such as:"
                },
                &["px", "em", "rem", "etc."],
            ),
        )
    }
}

/// Returns `true` if the given lowercased unit is a known CSS unit.
fn is_known_unit(unit: &str) -> bool {
    KNOWN_UNITS.contains(&unit)
}

/// Returns `true` if the dimension is used within a resolution context, where
/// the `x` unit is allowed.
fn is_in_resolution_context(node: &AnyCssDimension) -> bool {
    for ancestor in node.syntax().ancestors() {
        match ancestor.kind() {
            CssSyntaxKind::CSS_FUNCTION => {
                if let Some(function) = ancestor.cast::<CssFunction>() {
                    if let Ok(name) = function.name() {
                        if name.text().to_lowercase().ends_with("image-set") {
                            return true;
                        }
                    }
                }
            }
            CssSyntaxKind::CSS_QUERY_FEATURE_PLAIN => {
                if let Some(feature) = ancestor.cast::<CssQueryFeaturePlain>() {
                    if let Ok(name) = feature.name() {
                        if is_resolution_media_feature(&name.text().to_lowercase()) {
                            return true;
                        }
                    }
                }
            }
            CssSyntaxKind::CSS_QUERY_FEATURE_RANGE => {
                if let Some(feature) = ancestor.cast::<CssQueryFeatureRange>() {
                    if let Ok(name) = feature.left() {
                        if is_resolution_media_feature(&name.text().to_lowercase()) {
                            return true;
                        }
                    }
                }
            }
            CssSyntaxKind::CSS_GENERIC_PROPERTY => {
                if let Some(property) = ancestor.cast::<CssGenericProperty>() {
                    if let Ok(name) = property.name() {
                        if is_resolution_property(&name.text().to_lowercase()) {
                            return true;
                        }
                    }
                }
            }
            _ => {}
        }
    }
    false
}

fn is_resolution_media_feature(name: &str) -> bool {
    matches!(name, "resolution" | "min-resolution" | "max-resolution")
}

fn is_resolution_property(name: &str) -> bool {
    matches!(name, "image-resolution")
}

/// All known CSS units, lowercased. The `x` resolution unit is intentionally
/// excluded, as it is only valid within a resolution context and is handled
/// separately.
const KNOWN_UNITS: &[&str] = &[
    // Font-relative lengths
    "cap", "rcap", "ch", "rch", "em", "rem", "ex", "rex", "ic", "ric", "lh", "rlh", //
    // Viewport-percentage lengths
    "vh", "svh", "lvh", "dvh", "vw", "svw", "lvw", "dvw", "vi", "svi", "lvi", "dvi", "vb", "svb",
    "lvb", "dvb", "vmin", "svmin", "lvmin", "dvmin", "vmax", "svmax", "lvmax", "dvmax", //
    // Container query lengths
    "cqw", "cqh", "cqi", "cqb", "cqmin", "cqmax", //
    // Absolute lengths
    "cm", "mm", "q", "in", "pt", "pc", "px", //
    // Angles
    "deg", "grad", "rad", "turn", //
    // Duration
    "s", "ms", //
    // Frequency
    "hz", "khz", //
    // Resolution
    "dpi", "dpcm", "dppx", //
    // Flex
    "fr",
];
